protected void initializeDataAcessor(boolean _includeDisabledDiscounts)
{
    next initializeDataAcessor(_includeDisabledDiscounts);

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        pricingManager = new GUPRetailPricingDataManager(retailChannelTable.RecId, this.getTransactionIdString(), tempOrderItem, true);
        this.setPriceTreeName();
    }
}

protected void initChannelCurrency()
{
    next initChannelCurrency();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        str localChannelCurrency = RetailPricingSimulatorSalesTransaction::findByRef(salesTransactionId).ChannelCurrency;
        if (channelCurrency == '' || (localChannelCurrency != '' && localChannelCurrency != channelCurrency))
        {
            channelCurrency = localChannelCurrency;
        }          
    }
}

private void setPriceTreeName()
{
    GUPPriceTreeName gupPriceTreeName = GUPPricingTree::findPriceTreeNameByPricingSimulator(psSalesTransaction.SimulationName);

    if (this.pricingManager)
    {
        GUPRetailPricingDataManager gupPricingManager = this.pricingManager;
        Microsoft.Dynamics.Commerce.Runtime.DataModel.UnifiedPricingParameter unifiedPricingParameter = gupPricingManager.GetGlobalUnifiedPricingParameter();
        unifiedPricingParameter.PriceTreeName = gupPriceTreeName;
    }
}
